  "recovered_c": "#include <stdint.h>\n#include <stddef.h>\n\nuint64_t fn_20(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint8_t p[8];\n  uint64_t sd = arg;\n  size_t b;\n  size_t n;\n\n  if (out_cap < len) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  for (n = 0; n < 8; n++) {\n    p[n] = (uint8_t)n;\n  }\n\n  for (n = 7; n != 0; n--) {\n    uint64_t uVar3 = sd % (n + 1);\n    sd = sd / (n + 1);\n    uint8_t uVar1 = p[n];\n    p[n] = p[uVar3];\n    p[uVar3] = uVar1;\n  }\n\n  for (b = 0; b + 8 <= len; b += 8) {\n    for (n = 0; n < 8; n++) {\n      out[b + n] = in[p[n] + b];\n    }\n  }\n\n  for (; b < len; b++) {\n    out[b] = in[b];\n  }\n\n  return len;\n}\n"
}
